/* eslint-disable import/no-extraneous-dependencies */
module.exports = {
  '*.js': ['eslint --fix', 'prettier --write'],
  '*.md': absolutePaths => {
    // packages/ui/skills/lion-ui/references/**/*.md is generated by
    // `npm run skills:generate` (its formatting is owned by that script, not
    // prettier/markdownlint) and re-lints with pre-existing upstream issues
    // from @custom-elements-manifest/to-markdown, so it's excluded here the
    // same way it's excluded from the `lint:markdownlint` script.
    const filteredPaths = absolutePaths.filter(
      p => !p.includes('/packages/ui/skills/lion-ui/references/'),
    );
    if (filteredPaths.length === 0) {
      return [];
    }
    return [
      `prettier --write ${filteredPaths.join(' ')}`,
      `markdownlint --ignore '{.github/**/*.md,.changeset/*.md,**/CHANGELOG.md,packages/ui/_legacy-changelogs/*.md}' ${filteredPaths.join(' ')}`,
    ];
  },
  'package-lock.json': ['node ./scripts/lock-scan.mjs'],
  '*package.json': absolutePaths => {
    const sortPackages = [];
    absolutePaths.forEach(p => {
      sortPackages.push(`node ./scripts/sort-package-json.js ${p}`);
    });
    return [...sortPackages, `node ./scripts/lint-versions.js`];
  },
};
